        height += 1
        n -= height
    return height

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    print(max_pyramid_height(n))

def solve_pyramid_height(n):
    height = 0
    cubes_used = 0
    while cubes_used + (height + 1) <= n:
        height += 1
        cubes_used += height
    return height

if __name__ == "__main__":
    n = int(input())
    print(solve_pyramid_height(n))
